import json
import subprocess
import sys


def run_wc(*args):
    return subprocess.run([sys.executable, "wc.py", *args], capture_output=True, text=True)


def test_text_output_is_unchanged():
    out = run_wc("sample.txt").stdout
    assert out.splitlines()[:4] == ["lines: 4", "words: 12", "unique: 8", "the 3"]


def test_default_top_is_five():
    out = run_wc("sample.txt").stdout.splitlines()
    assert len(out) == 8
    assert out[4:8] == ["the 3", "cat 2", "sat 2", "ran 1"]


def test_top_before_filename():
    out = run_wc("--top", "2", "sample.txt").stdout.splitlines()
    assert out == ["lines: 4", "words: 12", "unique: 8", "the 3", "cat 2"]


def test_options_after_filename():
    out = run_wc("sample.txt", "--top", "2").stdout.splitlines()
    assert out == ["lines: 4", "words: 12", "unique: 8", "the 3", "cat 2"]


def test_json_output():
    r = run_wc("sample.txt", "--json")
    data = json.loads(r.stdout)
    assert data == {
        "lines": 4,
        "words": 12,
        "unique": 8,
        "top": [["the", 3], ["cat", 2], ["sat", 2], ["ran", 1], ["a", 1]],
    }


def test_json_with_top():
    data = json.loads(run_wc("--json", "--top", "2", "sample.txt").stdout)
    assert data["top"] == [["the", 3], ["cat", 2]]
    assert data["unique"] == 8


def test_missing_file():
    for args in (["no-such.txt"], ["no-such.txt", "--json"], ["--top", "3", "no-such.txt"]):
        r = run_wc(*args)
        assert r.returncode == 2
        assert r.stderr == f"error: no such file: no-such.txt\n"

